fn bin_search(a: &[i32], k: i32) -> bool {
    let mut left = 0;
    let mut right = a.len() as isize - 1; // Use isize for indexing

    while left <= right {
        let mid = (left + right) / 2; // Calculate the middle index
        if a[mid as usize] == k {
            return true; // Target found
        } else if a[mid as usize] < k {
            left = mid + 1; // Search in the right half
        } else {
            right = mid - 1; // Search in the left half
        }
    }
    false // Target not found
}

fn main() {
    let arr = [1, 2, 3, 4, 5];
    let target = 3;
    let result = bin_search(&arr, target);
    println!("Target found: {}", result); // Should print: Target found: true
}